import json,numpy as np
from PIL import Image
from scipy import ndimage
for name in ['reposition_q2','lift_big']:
 root=f'/app/output/{name}';m=json.load(open(root+'/meta.json'));im=np.array(Image.open(root+'/last/side.jpg'));d=np.load(root+'/depth_side.npy')[0].astype(float);K=np.array(m['cameras']['side']['intrinsic_cv']);T=np.array(m['cameras']['side']['cam2world_gl']);Y,X=np.mgrid[:240,:320];xx=(X-160)/K[0,0]*d;yy=-(Y-120)/K[1,1]*d;w=np.stack([xx,yy,-d,np.ones_like(d)],-1)@T.T;mask=(im.max(2)-im.min(2)<25)&(im[:,:,0]>35)&(im[:,:,0]<155)&(w[:,:,2]>.54)&(w[:,:,2]<.70)&(X>105)&(X<180)&(Y>105)&(Y<160);l,n=ndimage.label(mask);cs=[]
 for i in range(1,n+1):
  ys,xs=np.where(l==i)
  if len(xs)>20:
   p=w[ys,xs,:3];cs.append((len(xs),p.mean(0),np.quantile(p[:,2],[.1,.5,.9]),(xs.min(),ys.min(),xs.max(),ys.max())))
 print('\n',name,'q',np.array(m['proprio']['now'])[:7].round(3))
 for c in sorted(cs,reverse=True,key=lambda x:x[0])[:3]:print(c[0],c[1].round(4),c[2].round(4),c[3])
